//! `loom-daemon work-docs archive|check --plan` — marker-driven archival of
//! `WORK_PLAN.md` (issue #12635, slice 3 of #12589). Rules and layout:
//! `defaults/docs/work-docs-archive.md`.
//!
//! Unlike the work log there is no date logic: a section moves only when a
//! human (or a role) put `<!-- loom:plan-archive -->` on the line directly
//! above its heading, so an old date alone can never hide pending work. The
//! machine-generated `guide:plan-body` region is regenerated by Guide, is not
//! history, and is never moved or touched.

use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

use anyhow::{bail, Context, Result};
use chrono::NaiveDate;

use super::work_docs_archive::{atomic_write, read_regular, RootArgs};

const ACTIVE_FILE: &str = "WORK_PLAN.md";
const ARCHIVE_DIR: &str = "work_plan";
const INDEX_HEADING: &str = "## Archives";
const ARCHIVE_MARKER: &str = "<!-- loom:plan-archive -->";
const BODY_START: &str = "<!-- guide:plan-body:start -->";
const BODY_END: &str = "<!-- guide:plan-body:end -->";

fn archive_name(month: &str) -> String {
    format!("WORK_PLAN_{month}.md")
}

/// `WORK_PLAN_YYYY-MM.md` -> `YYYY-MM`.
fn archive_month(file_name: &str) -> Option<String> {
    let month = file_name.strip_prefix("WORK_PLAN_")?.strip_suffix(".md")?;
    NaiveDate::parse_from_str(&format!("{month}-01"), "%Y-%m-%d").ok()?;
    Some(month.to_string())
}

fn archive_preamble(month: &str) -> String {
    format!(
        "# Work Plan Archive — {month}\n\nSections moved byte-for-byte from \
         [WORK_PLAN.md](../WORK_PLAN.md) by `loom-daemon work-docs archive --plan`.\n\n"
    )
}

/// Heading level (1-6) of an ATX heading line.
fn heading_level(line: &str) -> Option<usize> {
    let hashes = line.chars().take_while(|c| *c == '#').count();
    ((1..=6).contains(&hashes) && line[hashes..].starts_with(' ')).then_some(hashes)
}

/// Per-line facts: inside the generated region (markers included) or inside a
/// fenced code block (headings and markers there are inert).
fn classify(lines: &[&str]) -> (Vec<bool>, Vec<bool>) {
    let mut generated = vec![false; lines.len()];
    let mut fenced = vec![false; lines.len()];
    let (mut in_body, mut in_fence) = (false, false);
    for (i, line) in lines.iter().enumerate() {
        let t = line.trim();
        if !in_body && !in_fence && t == BODY_START {
            in_body = true;
        }
        generated[i] = in_body;
        if in_body && t == BODY_END {
            in_body = false;
        }
        if !in_body && (t.starts_with("```") || t.starts_with("~~~")) {
            in_fence = !in_fence;
            fenced[i] = true;
        } else {
            fenced[i] = in_fence;
        }
    }
    (generated, fenced)
}

struct Plan {
    /// Half-open line ranges of marked sections (marker line included).
    moves: Vec<(usize, usize)>,
    /// Index section range, when `## Archives` exists.
    index: Option<(usize, usize)>,
    warnings: Vec<String>,
}

fn plan(lines: &[&str]) -> Result<Plan> {
    let (gen, fenced) = classify(lines);
    let heading_at = |i: usize| -> Option<usize> {
        if i < lines.len() && !gen[i] && !fenced[i] {
            heading_level(lines[i])
        } else {
            None
        }
    };
    let is_marker = |i: usize| lines[i].trim() == ARCHIVE_MARKER && !gen[i] && !fenced[i];
    let mut moves: Vec<(usize, usize)> = Vec::new();
    let mut warnings = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        if !is_marker(i) {
            i += 1;
            continue;
        }
        let Some(level) = heading_at(i + 1) else {
            warnings.push(format!(
                "line {}: {ARCHIVE_MARKER} is not directly above a heading: ignored",
                i + 1
            ));
            i += 1;
            continue;
        };
        if lines[i + 1].trim_end() == INDEX_HEADING {
            bail!("line {}: the {INDEX_HEADING} index cannot be archived", i + 1);
        }
        // The section runs to the next heading of the same or higher level, a
        // marker introducing such a heading, or the generated region.
        let mut end = i + 2;
        while end < lines.len() {
            if lines[end].trim() == BODY_START && !fenced[end] {
                break;
            }
            if heading_at(end).is_some_and(|l| l <= level) {
                break;
            }
            if is_marker(end) && heading_at(end + 1).is_some_and(|l| l <= level) {
                break;
            }
            end += 1;
        }
        if lines[i + 1..end]
            .iter()
            .any(|l| l.trim_start().starts_with("- [ ]"))
        {
            warnings.push(format!(
                "line {}: marked section \"{}\" still contains an open `- [ ]` item; moved \
                 because it is marked",
                i + 1,
                lines[i + 1].trim_end()
            ));
        }
        moves.push((i, end));
        i = end;
    }
    let index = (0..lines.len())
        .find(|&n| lines[n].trim_end() == INDEX_HEADING && !gen[n] && !fenced[n])
        .map(|start| {
            let mut end = start + 1;
            while end < lines.len()
                && lines[end].trim() != BODY_START
                && !is_marker(end)
                && heading_at(end).is_none()
            {
                end += 1;
            }
            (start, end)
        });
    Ok(Plan {
        moves,
        index,
        warnings,
    })
}

fn lines_of(text: &str) -> Vec<&str> {
    text.split_inclusive('\n').collect()
}

fn join(lines: &[&str]) -> String {
    let mut out = String::new();
    for l in lines {
        if !out.is_empty() && !out.ends_with('\n') {
            out.push('\n');
        }
        out.push_str(l);
    }
    out
}

fn generated_region(lines: &[&str]) -> String {
    let (gen, _) = classify(lines);
    let region: Vec<&str> = lines
        .iter()
        .zip(&gen)
        .filter(|(_, g)| **g)
        .map(|(l, _)| *l)
        .collect();
    join(&region)
}

/// Months with an archive file on disk.
fn existing_months(dir: &Path) -> Result<Vec<String>> {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(e) => return Err(e).with_context(|| format!("read {}", dir.display())),
    };
    let mut months = Vec::new();
    for entry in entries {
        let name = entry?.file_name().to_string_lossy().into_owned();
        if let Some(m) = archive_month(&name) {
            months.push(m);
        }
    }
    Ok(months)
}

fn index_text(months: &[String]) -> String {
    let mut text = format!("{INDEX_HEADING}\n\n");
    for m in months {
        text.push_str(&format!("- [{m}]({ARCHIVE_DIR}/{})\n", archive_name(m)));
    }
    text.push('\n');
    text
}

/// Line multiset of `lines`, excluding the index section.
fn tally(lines: &[&str], index: Option<(usize, usize)>) -> BTreeMap<String, usize> {
    let mut map = BTreeMap::new();
    for (n, l) in lines.iter().enumerate() {
        if index.is_some_and(|(s, e)| (s..e).contains(&n)) {
            continue;
        }
        *map.entry(l.trim_end_matches('\n').to_string()).or_default() += 1;
    }
    map
}

/// Move marked sections of `<root>/WORK_PLAN.md` into
/// `work_plan/WORK_PLAN_<this month>.md`. `today` is injected for tests.
pub(crate) fn archive_plan(root: &Path, today: NaiveDate, dry_run: bool) -> Result<String> {
    let active_path = root.join(ACTIVE_FILE);
    let Some(text) = read_regular(&active_path)? else {
        bail!("{} not found", active_path.display());
    };
    let lines = lines_of(&text);
    let found = plan(&lines)?;
    let warn: String = found
        .warnings
        .iter()
        .map(|w| format!("\nwarning: {w}"))
        .collect();
    if found.moves.is_empty() {
        return Ok(format!("no sections marked {ARCHIVE_MARKER}: nothing to do{warn}"));
    }

    let month = today.format("%Y-%m").to_string();
    let dir = root.join(ARCHIVE_DIR);
    if let Ok(meta) = fs::symlink_metadata(&dir) {
        if !meta.is_dir() {
            bail!("{} exists but is not a directory", dir.display());
        }
    }
    let archive_path = dir.join(archive_name(&month));
    let existing = read_regular(&archive_path)?;

    // Moved sections, verbatim.
    let moved: Vec<String> = found
        .moves
        .iter()
        .map(|&(s, e)| join(&lines[s..e]))
        .collect();
    for m in &moved {
        if existing.as_deref().is_some_and(|t| t.contains(m.as_str())) {
            bail!(
                "conflict: {} already holds an identical section; nothing written",
                archive_path.display()
            );
        }
    }
    let mut new_archive = existing.clone().unwrap_or_else(|| archive_preamble(&month));
    for m in &moved {
        if !new_archive.ends_with('\n') {
            new_archive.push('\n');
        }
        new_archive.push_str(m);
        if !m.ends_with('\n') {
            new_archive.push('\n');
        }
    }

    // Active file without the moved ranges; the index regenerated in place
    // (or, when absent, where the first moved section used to be).
    let mut months = existing_months(&dir)?;
    if !months.contains(&month) {
        months.push(month.clone());
    }
    months.sort_unstable_by(|a, b| b.cmp(a));
    let index_block = index_text(&months);
    let mut kept: Vec<&str> = Vec::new();
    let mut index_written = false;
    for (n, l) in lines.iter().enumerate() {
        if found.index.is_some_and(|(s, e)| (s..e).contains(&n)) {
            if !index_written {
                kept.push(&index_block);
                index_written = true;
            }
            continue;
        }
        if let Some(&(s, _)) = found.moves.iter().find(|&&(s, e)| (s..e).contains(&n)) {
            if !index_written && found.index.is_none() && n == s {
                kept.push(&index_block);
                index_written = true;
            }
            continue;
        }
        kept.push(l);
    }
    let new_active = join(&kept);

    // Conservation: the generated region is byte-identical, and every line
    // outside the index is either still active or inside a moved section.
    let new_lines = lines_of(&new_active);
    if generated_region(&lines) != generated_region(&new_lines) {
        bail!("conservation failed: the generated region would change; nothing written");
    }
    let before = tally(&lines, found.index);
    let mut after = tally(&new_lines, plan(&new_lines)?.index);
    for m in &moved {
        for (k, v) in tally(&lines_of(m), None) {
            *after.entry(k).or_default() += v;
        }
    }
    if before != after {
        bail!("conservation failed: line contents differ after the move; nothing written");
    }

    let report = format!(
        "{}{} marked section(s) -> {}; {ACTIVE_FILE}: {} -> {} lines{warn}",
        if dry_run { "dry run: " } else { "" },
        moved.len(),
        archive_path.display(),
        lines.len(),
        new_lines.len(),
    );
    if dry_run {
        return Ok(report);
    }
    fs::create_dir_all(&dir).with_context(|| format!("create {}", dir.display()))?;
    atomic_write(&archive_path, &new_archive)?;
    if let Err(e) = atomic_write(&active_path, &new_active) {
        let _ = match existing {
            Some(t) => fs::write(&archive_path, t),
            None => fs::remove_file(&archive_path),
        };
        return Err(e.context("write failed; archive rolled back"));
    }
    Ok(report)
}

/// Generated region intact, index links resolve, and every archive holds only
/// marker-introduced sections (so no unmarked section ever left the plan).
pub(crate) fn check_plan(args: &RootArgs) -> Result<String> {
    let root = &args.root;
    let active_path = root.join(ACTIVE_FILE);
    let Some(text) = read_regular(&active_path)? else {
        bail!("{} not found", active_path.display());
    };
    let lines = lines_of(&text);
    let starts = lines.iter().filter(|l| l.trim() == BODY_START).count();
    let ends = lines.iter().filter(|l| l.trim() == BODY_END).count();
    if starts != ends || starts > 1 {
        bail!("generated region markers are unbalanced ({starts} start, {ends} end)");
    }
    if let Some((s, e)) = plan(&lines)?.index {
        for line in &lines[s..e] {
            let Some(target) = line
                .split("](")
                .nth(1)
                .and_then(|r| r.trim_end().strip_suffix(')'))
            else {
                continue;
            };
            let ok = fs::symlink_metadata(root.join(target)).is_ok_and(|m| m.is_file());
            if !ok {
                bail!("index link {target} does not resolve to a regular file");
            }
        }
    }
    let dir = root.join(ARCHIVE_DIR);
    let months = existing_months(&dir)?;
    for month in &months {
        let path = dir.join(archive_name(month));
        let archived = read_regular(&path)?.unwrap_or_default();
        let body = archived
            .strip_prefix(&archive_preamble(month))
            .unwrap_or(&archived);
        if body.trim_start().lines().next() != Some(ARCHIVE_MARKER) {
            bail!(
                "{} holds content that does not start with {ARCHIVE_MARKER}: only marked \
                 sections may be archived",
                path.display()
            );
        }
    }
    Ok(format!("ok: {ACTIVE_FILE} consistent with {} archive file(s)", months.len()))
}

